// pointermove: ghi left/top mỗi event + đọc offsetWidth/offsetHeight → forced reflow mỗi move
fab.style.setProperty('left', `${nx}px`, 'important');
fab.style.setProperty('top', `${ny}px`, 'important');
const w = fab.offsetWidth;  // layout read sau layout write = reflow
const h = fab.offsetHeight;
// .btn có transition: transform 150ms + .btn:active { transform: scale(0.98) }
// thiếu will-change → không có compositor layer riêng

cases.good:
// pointerdown: cache dims, bake base left/top 1 lần, disable transition
const rect = fab.getBoundingClientRect();
dragStart = { x, y, baseLeft: rect.left, baseTop: rect.top, fabW: rect.width, fabH: rect.height, vw, vh };
fab.style.setProperty('transition', 'none', 'important');
// pointermove: stash delta, apply trong rAF (1/frame), transform compositor-only
fab.style.setProperty('transform', `translate3d(${tx}px, ${ty}px, 0)`, 'important');
// CSS: .cell-token-fab { will-change: transform !important; touch-action: none !important; }
// pointerup: bake transform → left/top 1 lần, clear transform
const r = fab.getBoundingClientRect();
fab.style.removeProperty('transform');
fab.style.setProperty('left', `${r.left}px`, 'important');

cases.bad:
// pointermove: đọc rect mỗi event + set --sb-top (top = layout property) mỗi move
const rect = container.getBoundingClientRect();  // layout read mỗi move
const deltaPercent = (deltaY / rect.height) * 100;
const value = clamp(startOffset + deltaPercent, 0, 95);
options.setYOffset(value);  // set --sb-top → top change → layout + paint
// thiếu will-change → không có compositor layer

cases.good:
// pointerdown: cache container rect 1 lần
containerRect = container.getBoundingClientRect();
// pointermove: stash deltaY, apply trong rAF, dùng transform compositor-only
// base transform là translateY(-50%), add drag delta on top
const deltaPx = (value - startOffset) * containerRect.height / 100;
block.style.transform = `translateY(calc(-50% + ${deltaPx}px))`;
// CSS: .subtitle-block.dragging { will-change: transform; } (chỉ khi drag, block lớn)
// pointerup: bake --sb-top 1 lần, restore transform
block.style.transform = '';
options.setYOffset(currentOffset);  // set --sb-top 1 lần cuối
